dati.risposta:
{
	"genere": "prevedi",
	"titolo": "Cosa succede durante l'attesa con await",
	"consegna": "Leggi attentamente ciascun frammento di codice e scrivi cosa restituisce la funzione `run()`, senza eseguirlo sul computer.",
	"modalita": "previsioni",
	"previsioni": [
		{
			"codice": "extends RefCounted

signal evento_completato(punti: int)


func run() -> int:
	var punteggio: int = 10
	_modifica_dopo.call_deferred()
	var bonus: int = await evento_completato
	return punteggio + bonus


func _modifica_dopo() -> void:
	evento_completato.emit(5)
",
			"domanda": "Quale numero intero restituisce la funzione run()?",
			"spiegazione": "`run()` imposta `punteggio` a 10, pianifica l'esecuzione di `_modifica_dopo()` nel frame successivo e si sospende su `await evento_completato`. Nel frame differito viene emesso il segnale con il valore `5`. L'await riceve il parametro, lo assegna a `bonus` e la funzione prosegue restituendo `10 + 5 = 15`."
		},
		{
			"codice": "extends RefCounted


func passo_a(registro: Array[String]) -> void:
	registro.append("A")


func passo_b(registro: Array[String]) -> void:
	registro.append("B")


func run() -> String:
	var registro: Array[String] = []
	passo_a(registro)
	passo_b(registro)
	return ",".join(registro)
",
			"domanda": "Quale testo restituisce la funzione run()?",
			"spiegazione": "Le due funzioni sono sincrone (non contengono `await`): `passo_a` aggiunge `"A"`, poi `passo_b` aggiunge `"B"`. Il metodo `join` unisce gli elementi con la virgola producendo `"A,B"`."
		},
		{
			"codice": "extends RefCounted

signal tick


func operazione_lenta(registro: Array[String]) -> void:
	registro.append("1")
	await tick
	registro.append("2")


func run() -> String:
	var registro: Array[String] = []
	operazione_lenta(registro)
	registro.append("3")
	tick.emit()
	return ",".join(registro)
",
			"domanda": "Quale testo restituisce la funzione run()?",
			"spiegazione": "Chiamando `operazione_lenta(registro)` senza `await`, la funzione aggiunge subito `"1"` e poi si sospende su `await tick`, restituendo immediatamente il controllo a `run()`. `run()` prosegue ed aggiunge `"3"`. Solo a quel punto viene eseguito `tick.emit()`, risvegliando `operazione_lenta` che aggiunge `"2"`. Il testo finale è `"1,3,2"`."
		},
		{
			"codice": "extends RefCounted

signal pronto


func azione_interna() -> int:
	await pronto
	return 40


func operazione() -> int:
	var valore: int = await azione_interna()
	return valore + 2


func run() -> int:
	pronto.emit.call_deferred()
	var totale: int = await operazione()
	return totale
",
			"domanda": "Quale numero intero restituisce la funzione run()?",
			"spiegazione": "`run()` pianifica l'emissione del segnale `pronto` in differita e attende `operazione()`, che a sua volta attende `azione_interna()`. All'emissione differita di `pronto`, `azione_interna()` si risveglia e restituisce 40. `operazione()` riceve 40, calcola `40 + 2 = 42` e lo restituisce a `run()`, che a sua volta restituisce 42."
		},
		{
			"codice": "extends RefCounted

signal passo

var valore: int = 0


func avvia() -> void:
	valore += 1
	await passo
	valore += 10


func run() -> int:
	avvia()
	avvia()
	passo.emit()
	return valore
",
			"domanda": "Quale numero intero restituisce la funzione run()?",
			"spiegazione": "La prima chiamata a `avvia()` porta `valore` a 1 e si sospende su `await passo`. La seconda chiamata a `avvia()` incrementa `valore` a 2 e si sospende sullo stesso segnale. Quando `run()` esegue `passo.emit()`, entrambe le coroutine in attesa vengono risvegliate dallo stesso segnale ed eseguono ciascuna `valore += 10` (2 + 10 + 10). Il valore finale restituito è 22."
		}
	]
}
